using System.Reflection;
using System.Security.Cryptography;
using System.Text.Json;
namespace LocalChat;
partial class MainWindow {
 string BundledRuff(){var asm=Assembly.GetExecutingAssembly();using var manifest=asm.GetManifestResourceStream("LocalChat.RUFF-SOURCE.json")??throw new Exception("Нет манифеста Ruff");using var doc=JsonDocument.Parse(manifest);var version=doc.RootElement.GetProperty("version").GetString()!;var hash=doc.RootElement.GetProperty("exeSha256").GetString()!;var path=Path.Combine(root,"tools","ruff",version,"ruff.exe");Directory.CreateDirectory(Path.GetDirectoryName(path)!);using(var license=asm.GetManifestResourceStream("LocalChat.ruff-license.txt")){if(license!=null){using var writer=File.Create(Path.Combine(Path.GetDirectoryName(path)!,"LICENSE.txt"));license.CopyTo(writer);}}if(!File.Exists(path)||Convert.ToHexString(SHA256.HashData(File.ReadAllBytes(path))).ToLowerInvariant()!=hash){using var input=asm.GetManifestResourceStream("LocalChat.ruff.exe")??throw new Exception("Нет встроенного Ruff");using(var output=File.Create(path))input.CopyTo(output);}if(Convert.ToHexString(SHA256.HashData(File.ReadAllBytes(path))).ToLowerInvariant()!=hash)throw new Exception("SHA-256 Ruff не совпал");return path;}
 async Task<string> RunCodeCheck(string name,string text,string checker,CancellationToken ct){checker=checker==""?(name.EndsWith(".json",StringComparison.OrdinalIgnoreCase)?"json":"ruff"):checker;if(!(await ApproveAsync("code_check","Статически проверить "+name+" с помощью "+checker+"? Проверяющая программа запускается локально, сам исходный код не исполняется.",ct)))return "Пользователь запретил действие. Не повторять.";string executable=checker=="ruff"?BundledRuff():checker=="bandit"?settings.BanditPath:"";if(checker=="bandit"&&executable=="")throw new Exception("Bandit не установлен автоматически. Выбери доверенный bandit.exe в настройках.");return await CodeAudit.Check(checker,name,text,executable,ct);}
 async Task CheckSelectedCode(){using var d=new OpenFileDialog{Title="Статическая проверка Python / JSON",Filter="Python или JSON|*.py;*.json"};if(d.ShowDialog(this)!=DialogResult.OK)return;var file=new FileInfo(d.FileName);if(file.Length>80000)throw new Exception("Для проверки выбери файл до 80 КБ");var text=await File.ReadAllTextAsync(file.FullName);await RunQuick(new("code_check",name:file.Name,text:text,server:file.Extension.ToLowerInvariant()==".json"?"json":"ruff"),"Проверь файл "+file.Name);}
}
